/*
 * Home in the reader's words (DBU-05). learnerHome has already decided what is up next, what
 * is complete and the order; this turns it into Strings keys plus the values that fill their
 * {tags} (each part fills its own sentence), dates in the learner's time zone, and the option
 * sets' words, icons and colours. A row's id is prefixed: a row is a Model named by its id.
 * A check-in (DBU-10) reads "Check-in, 2 minutes": its n is the minutes it takes. Once sent and
 * not answered it carries an Answer button (answerable).
 */
if (Inputs.steps === undefined || Inputs.upNext === undefined || Inputs.progress === undefined ||
  Inputs.counts === undefined || Inputs.kinds === undefined || Inputs.statuses === undefined) return;
const get = (m, k) => (m && typeof m.get === 'function' ? m.get(k) : m && m[k]);
const kinds = (Inputs.kinds || []).map((k) => ({ value: get(k, 'value'), learnerKey: get(k, 'learnerKey'), bg: get(k, 'bg'), fg: get(k, 'fg'), icon: get(k, 'icon') }));
const statuses = (Inputs.statuses || []).map((s) => ({ value: get(s, 'value'), kind: get(s, 'kind'), labelKey: get(s, 'labelKey'), bg: get(s, 'bg'), fg: get(s, 'fg') }));
const me = Inputs.me || {};
const plan = Inputs.plan || null;
const up = Inputs.upNext || {};

// The learner's own zone (their profile), else the browser's.
let zone = 'UTC';
try { zone = Intl.DateTimeFormat().resolvedOptions().timeZone || 'UTC'; } catch (e) { zone = 'UTC'; }
if (me.timezone) {
  try { new Intl.DateTimeFormat('en-GB', { timeZone: me.timezone }); zone = me.timezone; } catch (e) { /* keep the browser's */ }
}
const day = (iso) => (iso ? new Date(iso).toLocaleDateString('en-GB', { timeZone: zone, weekday: 'short', day: 'numeric', month: 'short' }) : '');
const time = (iso) => (iso ? new Date(iso).toLocaleTimeString('en-GB', { timeZone: zone, hour: '2-digit', minute: '2-digit', hourCycle: 'h23' }) : '');

const whenOf = (s) => {
  if (s.kind === 'live') {
    if (!s.startsAt) return { key: 'home.whenToBook', date: '', time: '' };
    if (s.status === 'booked') return { key: 'home.whenAt', date: day(s.startsAt), time: time(s.startsAt) };
    return { key: 'home.whenDay', date: day(s.startsAt), time: '' };
  }
  if (s.kind === 'homework') {
    if ((s.status === 'approved' || s.status === 'handed_in') && s.handedInAt) return { key: 'home.whenHandedIn', date: day(s.handedInAt), time: '' };
    return { key: s.dueAt ? 'home.whenDue' : 'home.whenDay', date: day(s.dueAt), time: '' };
  }
  if (s.answeredAt) return { key: 'home.whenAnswered', date: day(s.answeredAt), time: '' };
  if (s.sentAt) return { key: 'home.whenSent', date: day(s.sentAt), time: '' };
  if (s.sendsAt) return { key: 'home.whenDay', date: day(s.sendsAt), time: '' };
  if (s.afterTitle) return { key: 'home.whenAfter', date: '', time: '', what: s.afterTitle };
  return { key: 'home.whenLater', date: '', time: '' };
};

const steps = Array.isArray(Inputs.steps) ? Inputs.steps : [];
Outputs.rows = steps.map((s) => {
  const kind = kinds.find((k) => k.value === s.kind) || {};
  const status = statuses.find((x) => x.kind === s.kind && x.value === s.status) || {};
  const when = whenOf(s);
  return {
    id: 'home-step-' + s.id,
    stepId: s.id,
    kindKey: kind.learnerKey || '',
    n: String(s.kind === 'checkin' ? (s.minutesToAnswer || 2) : s.number),
    title: s.title || '',
    whenKey: when.key,
    date: when.date,
    time: when.time,
    what: when.what || '',
    statusKey: status.labelKey || '',
    statusBg: status.bg || 'var(--muted)',
    statusFg: status.fg || 'var(--muted-foreground)',
    icon: kind.icon || null,
    iconBg: kind.bg || 'var(--muted)',
    iconFg: kind.fg || 'var(--muted-foreground)',
    rowBg: s.current ? 'var(--homework-bg)' : 'var(--surface)',
    rowBorder: s.current ? 'var(--homework-border)' : 'var(--surface)',
    opens: s.kind === 'homework',
    answers: s.answerable === true
  };
});

Outputs.first = String(me.name || '').trim().split(' ')[0];
Outputs.hasPlan = !!plan;
Outputs.planTitle = plan ? plan.title : '';
Outputs.week = plan && plan.week ? String(plan.week) : '';
Outputs.preparing = steps.length === 0;
Outputs.hasSteps = steps.length > 0;
Outputs.countLive = String((Inputs.counts && Inputs.counts.live) || 0);
Outputs.countHomework = String((Inputs.counts && Inputs.counts.homework) || 0);
Outputs.progressDone = String(Inputs.progress.complete || 0);
Outputs.progressTotal = String(Inputs.progress.total || 0);
Outputs.progressPercent = Number(Inputs.progress.percent) || 0;

const hw = up.homework || null;
Outputs.hwShown = !!hw;
Outputs.hwNone = !hw;
Outputs.hwHeadKey = hw && hw.dueAt ? 'home.hwHead' : 'home.hwHeadNoDue';
Outputs.hwN = hw ? String(hw.number) : '';
Outputs.hwDate = hw ? day(hw.dueAt) : '';
Outputs.hwTitle = hw ? hw.title : '';
Outputs.hwBodyKey = hw ? ({ changes_asked: 'home.hwChangesAsked', handed_in: 'home.hwHandedIn' }[hw.status] || 'home.hwNotStarted') : '';
Outputs.hwStepId = hw ? hw.id : '';

const lv = up.live || null;
Outputs.liveShown = !!lv;
Outputs.liveNone = !lv;
Outputs.liveN = lv ? String(lv.number) : '';
Outputs.liveDate = lv ? day(lv.startsAt) : '';
Outputs.liveStart = lv ? time(lv.startsAt) : '';
Outputs.liveEnd = lv ? time(lv.endsAt) : '';
Outputs.liveTitle = lv ? lv.title : '';
Outputs.livePrep = lv ? lv.prepNote : '';
Outputs.hasPrep = !!(lv && lv.prepNote);
Outputs.joinLink = lv ? lv.meetingLink : '';
Outputs.hasJoin = !!(lv && lv.meetingLink);
Outputs.liveStepId = lv ? lv.id : '';
Outputs.liveStartsAt = lv ? lv.startsAt : '';
Outputs.liveDuration = lv ? lv.durationMin : 60;
Outputs.calDetails = plan ? plan.title : '';
Outputs.attendeeName = String(me.name || '');
Outputs.bookingLink = up.bookingLink || '';
Outputs.canBook = !!up.bookingLink;
Outputs.liveNoneKey = up.bookingLink ? 'home.liveNoneBook' : 'home.liveNoneWait';
Outputs.ready();
